CREATE TABLE users (id BIGINT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(120) NOT NULL, email VARCHAR(190) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, role VARCHAR(20) NOT NULL, active BOOLEAN NOT NULL, created_at TIMESTAMP NOT NULL);
CREATE TABLE artisan_profiles (id BIGINT AUTO_INCREMENT PRIMARY KEY, user_id BIGINT NOT NULL UNIQUE, shop_name VARCHAR(120) NOT NULL, craft VARCHAR(80), district VARCHAR(120), story VARCHAR(600), phone VARCHAR(40), status VARCHAR(20) NOT NULL, verification_note VARCHAR(300), CONSTRAINT fk_profile_user FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE categories (id BIGINT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(255) NOT NULL UNIQUE, district VARCHAR(255));
CREATE TABLE products (id BIGINT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(160) NOT NULL, description VARCHAR(3000) NOT NULL, price DECIMAL(12,2) NOT NULL, stock INT NOT NULL, materials VARCHAR(160), technique VARCHAR(100), district VARCHAR(80), image_url VARCHAR(500), artisan_id BIGINT NOT NULL, category_id BIGINT NOT NULL, active BOOLEAN NOT NULL, created_at TIMESTAMP NOT NULL, CONSTRAINT fk_product_artisan FOREIGN KEY(artisan_id) REFERENCES users(id), CONSTRAINT fk_product_category FOREIGN KEY(category_id) REFERENCES categories(id));
CREATE TABLE orders (id BIGINT AUTO_INCREMENT PRIMARY KEY, customer_id BIGINT NOT NULL, total DECIMAL(12,2) NOT NULL, status VARCHAR(30) NOT NULL, shipping_address VARCHAR(255) NOT NULL, created_at TIMESTAMP NOT NULL, CONSTRAINT fk_order_customer FOREIGN KEY(customer_id) REFERENCES users(id));
CREATE TABLE order_items (id BIGINT AUTO_INCREMENT PRIMARY KEY, order_id BIGINT NOT NULL, product_id BIGINT NOT NULL, artisan_id BIGINT NOT NULL, quantity INT NOT NULL, unit_price DECIMAL(12,2) NOT NULL, commission DECIMAL(12,2) NOT NULL, artisan_earnings DECIMAL(12,2) NOT NULL, CONSTRAINT fk_item_order FOREIGN KEY(order_id) REFERENCES orders(id), CONSTRAINT fk_item_product FOREIGN KEY(product_id) REFERENCES products(id), CONSTRAINT fk_item_artisan FOREIGN KEY(artisan_id) REFERENCES users(id));
CREATE TABLE order_status_history (id BIGINT AUTO_INCREMENT PRIMARY KEY, order_id BIGINT NOT NULL, status VARCHAR(30), note VARCHAR(500), created_at TIMESTAMP NOT NULL, CONSTRAINT fk_event_order FOREIGN KEY(order_id) REFERENCES orders(id));
CREATE TABLE earnings_ledger (id BIGINT AUTO_INCREMENT PRIMARY KEY, order_item_id BIGINT NOT NULL UNIQUE, artisan_id BIGINT NOT NULL, order_id BIGINT NOT NULL, gross_amount DECIMAL(12,2) NOT NULL, platform_commission DECIMAL(12,2) NOT NULL, artisan_amount DECIMAL(12,2) NOT NULL, payout_status VARCHAR(24) NOT NULL, recorded_at TIMESTAMP NOT NULL, CONSTRAINT fk_ledger_item FOREIGN KEY(order_item_id) REFERENCES order_items(id), CONSTRAINT fk_ledger_artisan FOREIGN KEY(artisan_id) REFERENCES users(id), CONSTRAINT fk_ledger_order FOREIGN KEY(order_id) REFERENCES orders(id));
CREATE INDEX idx_products_active_created ON products(active, created_at);
CREATE INDEX idx_order_customer_created ON orders(customer_id, created_at);
CREATE INDEX idx_order_items_artisan ON order_items(artisan_id);
